import os, re

def yukle(p): return open(p, encoding='utf-8').read()
def yaz(p, s): open(p, 'w', encoding='utf-8', newline='').write(s)
def rep(s, eski, yeni, n=1):
    assert s.count(eski) == n, eski[:80]
    return s.replace(eski, yeni)

# ---------- CheckInKarti: onFotografAc ----------
p = os.path.join('src', 'tasarim', 'CheckInKarti.tsx')
