"""Natural Earth 1:50m (kamu mali) -> Turkiye merkezli bolgesel harita SVG yollari.

Mercator izdusumu, gorunum kutusu 390 px genislik. Yollar RDP ile
sadelestiriliyor (0,35 px). Cikti: dunya-harita.json {genislik, yukseklik,
ulkeler: [{ad, d}], turkiye: d}
"""
import json, math, sys

GENISLIK = 390.0
LON_MIN, LON_MAX = 16.0, 56.0
LAT_MIN, LAT_MAX = 25.0, 50.0


def merc_y(lat):
    return math.log(math.tan(math.pi / 4 + math.radians(lat) / 2))


OLCEK = GENISLIK / (LON_MAX - LON_MIN)
Y_UST = merc_y(LAT_MAX)
Y_ALT = merc_y(LAT_MIN)
YUKSEKLIK = (Y_UST - Y_ALT) * math.degrees(1) * OLCEK


def izdus(lon, lat):
    x = (lon - LON_MIN) * OLCEK
    y = (Y_UST - merc_y(lat)) * math.degrees(1) * OLCEK
    return x, y


def rdp(pts, eps):
    if len(pts) < 3:
        return pts
    ax, ay = pts[0]
    bx, by = pts[-1]
    dx, dy = bx - ax, by - ay
    uz = math.hypot(dx, dy)
    en_uzak, idx = 0.0, 0
    for i in range(1, len(pts) - 1):
        px, py = pts[i]
        if uz == 0:
            d = math.hypot(px - ax, py - ay)
        else:
            d = abs(dy * px - dx * py + bx * ay - by * ax) / uz
        if d > en_uzak:
            en_uzak, idx = d, i
    if en_uzak > eps:
        return rdp(pts[: idx + 1], eps)[:-1] + rdp(pts[idx:], eps)
    return [pts[0], pts[-1]]


def halka_yolu(halka):
    pts = [izdus(lon, lat) for lon, lat in halka]
    # gorunum disinda kalan halkalari at (kaba kutu testi)
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    if max(xs) < -20 or min(xs) > GENISLIK + 20 or max(ys) < -20 or min(ys) > YUKSEKLIK + 20:
        return None
    pts = rdp(pts, 0.35)
    if len(pts) < 3:
        return None
    return 'M' + ' '.join(f'{x:.1f},{y:.1f}' for x, y in pts) + 'Z'


d = json.load(open('ne50.geojson', encoding='utf-8'))
ulkeler = []
turkiye = None
for f in d['features']:
    g = f['geometry']
    polys = g['coordinates'] if g['type'] == 'MultiPolygon' else [g['coordinates']]
    yollar = []
    for poly in polys:
        for halka in poly:  # dis halka + delikler (evenodd ile cizilecek)
            y = halka_yolu(halka)
            if y:
                yollar.append(y)
    if not yollar:
        continue
    ad = f['properties'].get('NAME') or f['properties'].get('ADMIN')
    kayit = {'ad': ad, 'd': ''.join(yollar)}
    if ad == 'Turkey':
        turkiye = kayit['d']
    else:
        ulkeler.append(kayit)

cikti = {'genislik': GENISLIK, 'yukseklik': round(YUKSEKLIK, 1), 'ulkeler': ulkeler, 'turkiye': turkiye}
json.dump(cikti, open('dunya-harita.json', 'w', encoding='utf-8'))
toplam = sum(len(u['d']) for u in ulkeler) + len(turkiye or '')
print('ulke', len(ulkeler), 'turkiye', bool(turkiye), 'boyut', toplam, 'yukseklik', round(YUKSEKLIK, 1))

