export function SekmeHapi<T extends string>({
  sekmeler,
  secili,
  onSec,
  yanPay = bosluk.sayfa,
}: {
  sekmeler: { anahtar: T; etiket: string }[]
  secili: T
  onSec: (anahtar: T) => void
  /** Baslangic genisligini ekrandan turetmek icin sayfanin yan payi. */
  yanPay?: number
}) {
